entries[255936] = { ["name"] = "Gürtelverzauberung: Schreckenshologrammprojektor", ["text"] = "Wirken in 2 sek.\nBenötigt Gürtel\nReagenzien:\nSturmsilbererz (20), Isoliertes Kabel (8)\nBringt dauerhaft ein spezialisiertes Gerät an Eurem Gürtel an, mit dem Ihr einen Gegner in Nahkampfreichweite für 5 Sek. in Furcht versetzen könnt.\n\nNur der Gürtel des Ingenieurs kann modifiziert werden und wird dadurch seelengebunden.\nBerufsausbilder:\nIngenieurskunst von Battle for Azeroth (85)\nKosten:\n5\n25" }
entries[255937] = { ["name"] = "Aschewelle", ["text"] = "Sofort 30 sek. Abklingzeit\n1 Aufladung\nWirbelt in weitem Bogen herum, fügt allen Gegnern innerhalb von 14 Metern vor Euch (321.86% der Angriffskraft) Strahlenschaden zu, belegt sie mit ' Nachstrom der Wahrheit ', was sie brennen lässt und ihnen zusätzlich [(65.28% der Angriffskraft) * (2.73077)] Schaden im Verlauf von 9 Sek. zufügt.\n\nDämonen und Untote werden außerdem für 5 Sek. betäubt.\n\nErzeugt 3 Heilige Kraft." }
entries[255940] = { ["name"] = "Gürtelverzauberung: Ellbogenfreiheit", ["text"] = "Wirken in 2 sek.\nBenötigt Gürtel\nReagenzien:\nSturmsilbererz (20), Isoliertes Kabel (8)\nBringt dauerhaft ein spezialisiertes Gerät an Eurem Gürtel an, mit dem Ihr Euer aktuelles Ziel zurückstoßen könnt. Teilt sich die Abklingzeit mit Tränken.\n\nNur der Gürtel des Ingenieurs kann modifiziert werden und wird dadurch seelengebunden.\nBerufsausbilder:\nIngenieurskunst von Battle for Azeroth (85)\nKosten:\n5\n25" }
