entries[256070] = { ["name"] = "Elektroschocker zur Reittiermotivierung", ["text"] = "Wirken in 2 sek.\nReagenzien:\nMoneliterz (12), Sturmsilbererz (5), Isoliertes Kabel (10)\nStellt einen Elektroschocker zur Reittiermotivierung her.\nBerufsausbilder:\nIngenieurskunst von Battle for Azeroth (25)\nKosten:\n1\n\nBenutzen: Erhöht 10 Sek. lang die Reitgeschwindigkeit um 10%. Bis zu 5-mal stapelbar. Durch erhöhte Motivation kann Euer Reittier desorientiert werden.\n\nNicht mit anderen Effekten zur Erhöhung der Reitgeschwindigkeit stapelbar.\n50 Aufladungen\n\"Bei der Konzipierung dieses Geräts kamen einige Tiere zu Schaden. Es geht ihnen aber schon wieder besser... den meisten zumindest.\"" }
entries[256071] = { ["name"] = "Elektroschocker zur Reittiermotivierung", ["text"] = "Wirken in 2 sek.\nReagenzien:\nMoneliterz (10), Sturmsilbererz (5), Isoliertes Kabel (8)\nVerringert die erforderlichen Materialien zur Herstellung eines Elektroschockers zur Reittiermotivierung.\nBerufsausbilder:\nIngenieurskunst von Battle for Azeroth (50)\nKosten:\n2\n\nBenutzen: Erhöht 10 Sek. lang die Reitgeschwindigkeit um 10%. Bis zu 5-mal stapelbar. Durch erhöhte Motivation kann Euer Reittier desorientiert werden.\n\nNicht mit anderen Effekten zur Erhöhung der Reitgeschwindigkeit stapelbar.\n50 Aufladungen\n\"Bei der Konzipierung dieses Geräts kamen einige Tiere zu Schaden. Es geht ihnen aber schon wieder besser... den meisten zumindest.\"" }
entries[256072] = { ["name"] = "Elektroschocker zur Reittiermotivierung", ["text"] = "Wirken in 2 sek.\nReagenzien:\nMoneliterz (8), Sturmsilbererz (4), Isoliertes Kabel (6)\nVerringert erheblich die erforderlichen Materialien zur Herstellung eines Elektroschockers zur Reittiermotivierung.\nWeltquest:\nArbeitsauftrag: Elektroschocker zur Reittiermotivierung\nZone:\nDas Sturmsangtal\n\nWeltquest:\nArbeitsauftrag: Elektroschocker zur Reittiermotivierung\nZone:\nZuldazar\n\nBenutzen: Erhöht 10 Sek. lang die Reitgeschwindigkeit um 10%. Bis zu 5-mal stapelbar. Durch erhöhte Motivation kann Euer Reittier desorientiert werden.\n\nNicht mit anderen Effekten zur Erhöhung der Reitgeschwindigkeit stapelbar.\n50 Aufladungen\n\"Bei der Konzipierung dieses Geräts kamen einige Tiere zu Schaden. Es geht ihnen aber schon wieder besser... den meisten zumindest.\"" }
