entries[256261] = { ["name"] = "Messerkrallen", ["text"] = "Nahkampfreichweite\nSofort\nReißt mit messerscharfen Krallen an einem Gegner und verursacht körperlichen Schaden sowie 6 Sek. lang alle 1 Sek. zusätzlichen körperlichen Schaden." }
entries[256274] = { ["name"] = "Verhexter Blick", ["text"] = "Sofort\nVerstärkt das Augenlicht des Zaubernden auf übernatürliche Weise, was seine kritische Trefferchance 5 Sek. lang um 100% erhöht." }
