entries[256688] = { ["name"] = "Teerfalle", ["text"] = "Unbegrenzte Reichweite\nSofort\nSchleudert eine Teerfalle an den Zielort, die 30 Sek. lang um sich herum eine Teerpfütze mit einem Radius von 8 Metern bildet, sobald sich ihr der erste Gegner nähert. Die Bewegungsgeschwindigkeit aller Gegner wird um 80% verringert, solange sie sich im Effektbereich befinden. Die Falle bleibt 1 Min. lang bestehen." }
