entries[256789] = { ["name"] = "Doppelbogen der Küste", ["text"] = "Wirken in 3 sek.\nReagenzien:\nSternenholz (8), Sturmbalg (25), Kalzifizierter Knochen (20), Expulsom (3)\nOptionale Reagenzien:\n[] (#48)\nVerringert erheblich die erforderlichen Materialien zur Herstellung eines Doppelbogens der Küste.\nVerkäufer:\nHorterin Jena\nZone:\nVol'dun\nVoldunai - Respektvoll\nKosten:\n1200\n\nHorde\nDoppelbogen der Küste\nWird beim Anlegen gebunden\nDistanz Bogen\n12 - 16 Schaden Geschwindigkeit 3.00\n(4.7 Schaden pro Sekunde)\n+6 Beweglichkeit\n+9 Ausdauer\nHaltbarkeit 100 / 100\n50\nAllianz\nDoppelbogen der Küste\nWird beim Anlegen gebunden\nDistanz Bogen\n12 - 16 Schaden Geschwindigkeit 3.00\n(4.7 Schaden pro Sekunde)\n+6 Beweglichkeit\n+9 Ausdauer\nHaltbarkeit 100 / 100\n50" }
entries[256790] = { ["name"] = "Rauer Lederharnisch", ["text"] = "Wirken in 3.5 sek.\nReagenzien:\nRaues Leder (25)\nStellt einen rauen Lederharnisch her.\nBeruf:\nLederverarbeitung von Battle for Azeroth (50)\nLehrer:\nXanjo\nZone:\nZuldazar\nKosten:\n2\n\nBenutzen: Verhindert 2 Stunden lang, dass der Spielercharakter beim Reiten in Kul Tiras und Zandalar benommen wird.\n\nDie Dauer ist für Lederverarbeiter vervierfacht." }
entries[256791] = { ["name"] = "Trommeln des Mahlstroms", ["text"] = "Wirken in 2 sek.\nReagenzien:\nRaues Leder (25), Blutbefleckter Knochen (10)\nStellt Trommeln des Mahlstroms her.\nBeruf:\nLederverarbeitung von Battle for Azeroth (75)\nLehrer:\nXanjo\nZone:\nZuldazar\nKosten:\n3\n50\n\nTrommeln des Mahlstroms" }
entries[256792] = { ["name"] = "Schimmerschuppentauchanzug", ["text"] = "Wirken in 3.5 sek.\nReagenzien:\nSchimmerschuppe (15), Raues Leder (10)\nStellt einen Schimmerschuppentauchanzug her.\nBeruf:\nLederverarbeitung von Battle for Azeroth (50)\nLehrer:\nXanjo\nZone:\nZuldazar\nKosten:\n2\n\nBenutzen: Legt einen Taucheranzug an, der Eure Schwimmgeschwindigkeit um 100% erhöht. Hält 15 Min. lang an." }
entries[256793] = { ["name"] = "Schimmerschuppentauchhelm", ["text"] = "Wirken in 3.5 sek.\nReagenzien:\nSchimmerschuppe (10), Raues Leder (5)\nStellt einen Schimmerschuppentauchhelm her.\nBeruf:\nLederverarbeitung von Battle for Azeroth (50)\nLehrer:\nXanjo\nZone:\nZuldazar\nKosten:\n2\n\nBenutzen: Legt einen Taucherhelm an, der Euch unter Wasser atmen lässt. Hält 15 Min. lang an." }
