entries[256819] = { ["name"] = "Mal von Golganneth", ["text"] = "Ca. 1.8 Procs pro Minute\nEure Schaden verursachenden Fähigkeiten haben eine Chance, an der Position Eures Ziels einen wütenden Sturm zu erschaffen, der innerhalb von 6 Metern im Verlauf von 6 Sek. ( 172 * 6) Naturschaden verursacht, der auf alle betroffenen Gegner aufgeteilt wird.\n\nGolganneths donnernde Wut\nWenn Euch das Pantheon Macht verleiht, rufen Eure automatischen Angriffe eine Blitzexplosion hervor, die allen Gegnern innerhalb von 8 Metern um das Ziel [ 1 * (Haupthandwaffen-Min-Grundgeschwindigkeit) * 96 ] Naturschaden zufügt. Hält 15 Sek. lang an." }
entries[256820] = { ["name"] = "Wütender Sturm", ["text"] = "100 Meter Reichweite\nSofort\nEure Schaden verursachenden Fähigkeiten haben eine Chance, an der Position Eures Ziels einen wütenden Sturm zu erschaffen, der innerhalb von 6 Metern im Verlauf von 6 Sek. ( 172 * 6) Naturschaden verursacht, der auf alle betroffenen Gegner aufgeteilt wird.\n\nGolganneths donnernde Wut\nWenn Euch das Pantheon Macht verleiht, rufen Eure automatischen Angriffe eine Blitzexplosion hervor, die allen Gegnern innerhalb von 8 Metern um das Ziel [ 1 * (Haupthandwaffen-Min-Grundgeschwindigkeit) * 96 ] Naturschaden zufügt. Hält 15 Sek. lang an." }
entries[256821] = { ["name"] = "Mal von Golganneth", ["text"] = "Sofort\nEure Schaden verursachenden Fähigkeiten haben eine Chance, an der Position Eures Ziels einen wütenden Sturm zu erschaffen, der innerhalb von 6 Metern im Verlauf von 6 Sek. ( 172 * 6) Naturschaden verursacht, der auf alle betroffenen Gegner aufgeteilt wird.\n\nGolganneths donnernde Wut\nWenn Euch das Pantheon Macht verleiht, rufen Eure automatischen Angriffe eine Blitzexplosion hervor, die allen Gegnern innerhalb von 8 Metern um das Ziel [ 1 * (Haupthandwaffen-Min-Grundgeschwindigkeit) * 96 ] Naturschaden zufügt. Hält 15 Sek. lang an." }
entries[256822] = { ["name"] = "Mal von Eonar", ["text"] = "Ca. 1.2 Procs pro Minute\nEure Heileffekte haben eine Chance, in der Nähe eine Smaragdblüte wachsen zu lassen, die einen zufälligen verletzten Verbündeten alle 2 Sek. um 275 Gesundheit heilt. Hält 12 Sek. lang an.\n\nEonars tiefgrüne Umarmung\nWenn Euch das Pantheon Macht verleiht, gewähren Eure nächsten 4 Einsätze von direkter Heilung dem Ziel einen Schild, der 30 Sek. lang 414 Schaden verhindert." }
