entries[256885] = { ["name"] = "Runenmal", ["text"] = "40 Meter Reichweite\nWirken in 2 sek.\nBelegt den Gegner mithilfe eines Mals mit einer verfluchten Rune, die 6 Sek. lang alle 1 Sek. Schattenschaden verursacht. Beim Ablauf oder beim Bannen des Mals explodiert die Rune und fügt allen Gegnern in der Nähe zusätzlichen Schattenschaden zu." }
